typedef struct {
    const int *code; size_t n; size_t ip;
} Program;

void prog_init(Program *p, const int *code, size_t n);
bool prog_fetch(Program *p, int *out);

typedef struct {
    IntVec stack;
    IntVec trace;
    int    steps;
} VM;

void vm_init(VM *vm);
